function escapeHtml(s) {
    if (s == null) {
        return '';
    }
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function escapeAttr(s) {
    if (s == null) {
        return '';
    }
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function toE164UsPhone(phone) {
    var d = String(phone).replace(/\D/g, '');
    if (d.length === 10) {
        return '+1' + d;
    }
    if (d.length === 11 && d.charAt(0) === '1') {
        return '+' + d;
    }
    return d.length ? '+' + d : '';
}

function distanceMeters(lat1, lng1, lat2, lng2) {
    var R = 6371000;
    var p1 = lat1 * Math.PI / 180;
    var p2 = lat2 * Math.PI / 180;
    var dp = (lat2 - lat1) * Math.PI / 180;
    var dl = (lng2 - lng1) * Math.PI / 180;
    var x = Math.sin(dp / 2) * Math.sin(dp / 2) +
        Math.cos(p1) * Math.cos(p2) * Math.sin(dl / 2) * Math.sin(dl / 2);
    return 2 * R * Math.atan2(Math.sqrt(x), Math.sqrt(1 - x));
}

/**
 * Resolves a hero photo URL + html_attributions via Places Details.
 * Requires Places API (and billing) enabled for the Maps API key.
 */
function loadPlacePhoto(placesService, model, callback) {
    var PSC = google.maps.places.PlacesServiceStatus;

    function finishDetails(placeId) {
        placesService.getDetails({
            placeId: placeId,
            fields: ['photos', 'html_attributions']
        }, function(place, status) {
            if (status !== PSC.OK || !place || !place.photos || !place.photos.length) {
                callback(null, null, status);
                return;
            }
            var url = place.photos[0].getUrl({ maxWidth: 800, maxHeight: 520 });
            callback(url, place.html_attributions || [], status);
        });
    }

    if (model.googlePlaceId) {
        finishDetails(model.googlePlaceId);
        return;
    }

    var e164 = toE164UsPhone(model.phone);
    if (e164 && typeof placesService.findPlaceFromPhoneNumber === 'function') {
        placesService.findPlaceFromPhoneNumber({
            phoneNumber: e164,
            fields: ['place_id']
        }, function(results, status) {
            if (status === PSC.OK && results && results[0] && results[0].place_id) {
                finishDetails(results[0].place_id);
                return;
            }
            findByTextQuery();
        });
    } else {
        findByTextQuery();
    }

    function findByTextQuery() {
        var query = model.name + ', ' + model.address_1 + ', ' + model.address_2;
        placesService.findPlaceFromQuery({
            query: query,
            fields: ['place_id', 'geometry']
        }, function(results, status) {
            if (status !== PSC.OK || !results || !results[0] || !results[0].place_id) {
                callback(null, null, status);
                return;
            }
            var r = results[0];
            if (r.geometry && r.geometry.location) {
                var d = distanceMeters(
                    model.lat,
                    model.lng,
                    r.geometry.location.lat(),
                    r.geometry.location.lng()
                );
                if (d > 650) {
                    callback(null, null, 'TOO_FAR');
                    return;
                }
            }
            finishDetails(r.place_id);
        });
    }
}

var ViewModel = function() {

    var self = this;

    // ** self.markerList is an empty array that is populated the google map markers information ** //

    self.markerList = ko.observableArray([]);

    function loadData() {
        if (typeof google === 'undefined' || !google.maps || !google.maps.places || !map) {
            return false;
        }
        var placesService = new google.maps.places.PlacesService(map);
        var markers = self.markerList();
        var photoIdx = 0;

        function nextPhoto() {
            if (photoIdx >= Model.length) {
                return;
            }
            var i = photoIdx;
            photoIdx += 1;
            loadPlacePhoto(placesService, Model[i], function(url, attributions, status) {
                if (markers[i]) {
                    if (url) {
                        markers[i].pic = url;
                    } else if (status) {
                        markers[i].photoStatus = status;
                        if (window && window.console && console.log) {
                            console.log('[Places photo missing]', Model[i].name, status);
                        }
                    }
                    if (attributions && attributions.length) {
                        markers[i].photoAttributions = attributions;
                    }
                }
                window.setTimeout(nextPhoto, 120);
            });
        }

        nextPhoto();
        return false;
    }

    // ** Add custom marker icon to replace default google maps marker ** //

    var pinIcon = new google.maps.MarkerImage('images/pegasus.png', /* Custom map marker */
        null, /* size is determined at runtime */
        null, /* origin is 0,0 */
        null, /* anchor is bottom center of the scaled image */
        new google.maps.Size(42, 42)
    );

    var infoWindow = new google.maps.InfoWindow({
        maxWidth: 300,
        pixelOffset: new google.maps.Size(0, -6)
    });

    google.maps.event.addListener(infoWindow, 'domready', function() {
        var root = document.getElementById('location-card-root');
        if (!root) {
            return;
        }
        var shell = root.closest('.gm-style-iw-c');
        if (shell) {
            shell.classList.add('location-infowindow');
        }
        var closeEl = root.querySelector('.location-card__close');
        if (closeEl) {
            closeEl.onclick = function(event) {
                if (event) {
                    event.preventDefault();
                    event.stopPropagation();
                }
                infoWindow.close();
                return false;
            };
        }
    });

    function stopAnimation(m) {
        setTimeout(function() {
            m.setAnimation(null);
        }, 3500);
    }

    var PHOTO_ICON_SVG =
        '<svg class="location-card__placeholder-svg" xmlns="http://www.w3.org/2000/svg" width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' +
        '<path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/>' +
        '<circle cx="12" cy="13" r="3.5"/>' +
        '</svg>';

    function activeMarker(m) {
        var picSrc = m.pic ? String(m.pic) : '';
        var legacySvg = picSrc.indexOf('data:image/svg+xml') === 0;
        var site = m.url ? escapeAttr(m.url) : '';
        var hasPhoto = !!(picSrc && !legacySvg);
        var mediaHtml;
        if (hasPhoto) {
            mediaHtml =
                '<img class="location-card__img" src="' + escapeAttr(picSrc) + '" alt="">';
        } else {
            var statusNote = m.photoStatus ? (' (' + escapeHtml(m.photoStatus) + ')') : '';
            mediaHtml =
                '<div class="location-card__placeholder" role="img" aria-label="No photo available">' +
                '<span class="location-card__placeholder-icon">' + PHOTO_ICON_SVG + '</span>' +
                '<span class="location-card__placeholder-caption">No photo' + statusNote + '</span>' +
                '</div>';
        }

        var creditHtml = '';
        if (hasPhoto && m.photoAttributions && m.photoAttributions.length) {
            creditHtml = '<div class="location-card__photo-credit">' + m.photoAttributions.join('') + '</div>';
        }

        infoWindow.setContent(
            '<article id="location-card-root" class="location-card">' +
            '<header class="location-card__topbar">' +
            '<button type="button" class="location-card__close" aria-label="Close"></button>' +
            '</header>' +
            '<div class="location-card__media-wrap">' +
            '<div class="location-card__media">' + mediaHtml + '</div>' +
            creditHtml +
            '</div>' +
            '<div class="location-card__body">' +
            '<p class="location-card__title">' + escapeHtml(m.title) + '</p>' +
            '<div class="location-card__address">' +
            escapeHtml(m.address_1) + '<br>' + escapeHtml(m.address_2) +
            '</div>' +
            '<p class="location-card__phone">' + escapeHtml(m.phone) + '</p>' +
            (site
                ? '<a class="location-card__link" href="' + site + '" target="_blank" rel="noopener noreferrer">Website<span class="location-card__link-arrow">&nbsp;↗</span></a>'
                : '') +
            '</div>' +
            '</article>'
        );

        infoWindow.open(map, m);

        if (m.getAnimation() !== null) {
            m.setAnimation(null);
        } else {
            m.setAnimation(google.maps.Animation.BOUNCE);
        }

        map.panTo(m.position);
    }

    // ** Adding the markers to the map for each location in the array. ** //

    var marker;
    for (var i = 0; i < Model.length; i++) {
        marker = new google.maps.Marker({
            position: new google.maps.LatLng(Model[i].lat, Model[i].lng),
            map: map,
            icon: pinIcon,
            title: Model[i].name,
            address_1: Model[i].address_1,
            address_2: Model[i].address_2,
            phone: Model[i].phone,
            url: Model[i].url,
            animation: google.maps.Animation.DROP
        });

        self.markerList.push(marker); // ** Populate self.markerList array with marker information ** //

        google.maps.event.addListener(marker, 'click', function() {
            activeMarker(this);
            stopAnimation(this);
        });

        $('#uiList .dropdown-menu').append('<li><a>' + Model[i].name +
            '<br>' + Model[i].address_1 + '<br>' + Model[i].address_2 +
            '<br>' + Model[i].phone + '<br>' + '<hr>' + '</a></li>');

        $('#uiList .dropdown-menu li a').last().bind('click', function(markerRef) {
            return function() {
                activeMarker(markerRef);
                stopAnimation(markerRef);
            };

        }(marker));

    }

    self.filter = function() {

        var str = $('#filter').val();

        str = str.toLowerCase().replace(/\b[a-z]/g, function(chr) {
            return chr.toUpperCase();
        });

        $(".dropdown-menu > li").each(function() {
            if ($(this).text().search(str) > -1) {
                $(this).show();
            } else {
                $(this).hide();
            }
        });

        for (var fi = 0; fi < self.markerList().length; fi++) {
            self.markerList()[fi].setMap(self.markerList()[fi].title.search(str) > -1 ? map : null);
        }
    };

    $(loadData);

    // ** Dropdown click functionality ** //

    $('#uiList').click(function() {
        $('.dropdown-menu').toggle().addClass('slideDown');
    });
};

//** Initialize Google Maps **//

var map = new google.maps.Map(document.getElementById('map-canvas'), {
    center: new google.maps.LatLng(32.789356, -96.801788),
    zoom: 13,
    disableDefaultUI: true,
});

$(document).ready(function() {
    ko.applyBindings(new ViewModel());
});
